import re
from typing import List, Tuple

Token = Tuple[str, str]  # (type, value)

def eval_expr(s: str) -> float:
    token_spec = [
        ('NUMBER',   r'\d+(\.\d+)?'),
        ('OP',       r'[\+\-\*/\^]'),
        ('LPAREN',   r'\('),
        ('RPAREN',   r'\)'),
        ('SPACE',    r'\s+'),
        ('MISMATCH', r'.'),
    ]
    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_spec)
    tokens: List[Token] = []
    for mo in re.finditer(tok_regex, s):
        kind = mo.lastgroup
        val = mo.group()
        if kind == 'SPACE':
            continue
        if kind == 'MISMATCH':
            raise ValueError(f"Unknown character: {val}")
        tokens.append((kind, val))
    if not tokens:
        raise ValueError("Empty expression")
    # Parser implementing precedence:
    # expression -> term ((+|-) term)*
    # term -> power ((*|/) power)*
    # power -> unary (^ power)?
    # unary -> - unary | primary
    # primary -> NUMBER | ( expression )
    pos = 0
    def peek():
        return tokens[pos] if pos < len(tokens) else ('EOF','')
    def consume(expected_type=None, expected_val=None):
        nonlocal pos
        if pos >= len(tokens):
            return None
        tok = tokens[pos]
        if expected_type and tok[0] != expected_type:
            return None
        if expected_val and tok[1] != expected_val:
            return None
        pos += 1
        return tok
    def parse_expression() -> float:
        nonlocal pos
        value = parse_term()
        while True:
            tok = peek()
            if tok[0] == 'OP' and tok[1] in ('+','-'):
                consume('OP')
                rhs = parse_term()
                if tok[1] == '+':
                    value = value + rhs
                else:
                    value = value - rhs
            else:
                break
        return value
    def parse_term() -> float:
        value = parse_power()
        while True:
            tok = peek()
            if tok[0] == 'OP' and tok[1] in ('*','/'):
                consume('OP')
                rhs = parse_power()
                if tok[1] == '*':
                    value = value * rhs
                else:
                    if rhs == 0:
                        raise ZeroDivisionError("Division by zero")
                    value = value / rhs
            else:
                break
        return value
    def parse_power() -> float:
        # right-associative: a ^ b ^ c = a ^ (b ^ c)
        left = parse_unary()
        tok = peek()
        if tok[0] == 'OP' and tok[1] == '^':
            consume('OP')
            right = parse_power()
            try:
                # pow with floats
                value = left ** right
            except ZeroDivisionError:
                raise
            except Exception as e:
                # domain errors (e.g., negative ** fractional) raise ValueError
                raise ValueError("Invalid exponentiation") from e
            return value
        return left
    def parse_unary() -> float:
        tok = peek()
        if tok[0] == 'OP' and tok[1] == '-':
            consume('OP')
            val = parse_unary()
            return -val
        return parse_primary()
    def parse_primary() -> float:
        tok = peek()
        if tok[0] == 'NUMBER':
            consume('NUMBER')
            try:
                return float(tok[1])
            except:
                raise ValueError("Invalid number")
        if tok[0] == 'LPAREN':
            consume('LPAREN')
            val = parse_expression()
            if not consume('RPAREN'):
                raise ValueError("Unbalanced parentheses")
            return val
        raise ValueError("Expected number or '('")
    result = parse_expression()
    if pos != len(tokens):
        raise ValueError("Malformed expression")
    return float(result)

