Token = Tuple[str, str]

def eval_expr(s: str) -> float:
    token_spec = [
        ('NUMBER',   r'\d+(\.\d+)?'),
        ('OP',       r'[\+\-\*/\^]'),
        ('LPAREN',   r'\('),
        ('RPAREN',   r'\)'),
        ('SPACE',    r'\s+'),
