        value = mo.group()
        if kind == 'SPACE':
            continue
        if kind == 'MISMATCH':
            raise ValueError(f"Invalid character: {value!r}")
        tokens.append((kind, value))
    if not tokens:
        raise ValueError("Empty expression")
    # Parser with recursive descent respecting precedence:
    # expr -> addsub
    # addsub -> muldiv ((+|-) muldiv)*
    # muldiv -> unary ((*|/) unary)*
    # unary -> '-' unary | power
    # power -> primary (^ power)?
    # primary -> NUMBER | (expr)
    pos = 0
    n = len(tokens)

    def peek():
        return tokens[pos] if pos < n else (None, None)

    def consume(expected_kind=None, expected_value=None):
        nonlocal pos
        if pos >= n:
            return None
        kind, val = tokens[pos]
        if expected_kind and kind != expected_kind:
            return None
        if expected_value and val != expected_value:
            return None
        pos += 1
        return (kind, val)

    def parse_expr():
        val = parse_addsub()
        if pos != n:
            raise ValueError("Unexpected token after expression")
        return val

    def parse_addsub():
        val = parse_muldiv()
        while True:
            k, v = peek()
            if k == 'OP' and v in ('+', '-'):
                consume()
                rhs = parse_muldiv()
                if v == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    def parse_muldiv():
        val = parse_unary()
        while True:
            k, v = peek()
            if k == 'OP' and v in ('*', '/'):
                consume()
                rhs = parse_unary()
                if v == '*':
                    val = val * rhs
                else:
                    if rhs == 0:
                        raise ZeroDivisionError("division by zero")
                    val = val / rhs
            else:
                break
        return val

    def parse_unary():
        k, v = peek()
        if k == 'OP' and v == '-':
            consume()
            return -parse_unary()
        return parse_power()

