def parse_csv_line(s: str) -> List[str]:
    fields: List[str] = []
    i = 0
    n = len(s)
    while True:
        if i >= n:
            # end of line; if empty string -> single empty field
            if not fields:
                return [""]
            return fields
        # Check if field starts with quote
        if s[i] == '"':
            i += 1
            field_chars = []
            while True:
                if i >= n:
                    raise ValueError("Unterminated quoted field")
                ch = s[i]
                if ch == '"':
                    # Could be escaped quote or closing quote
                    if i + 1 < n and s[i + 1] == '"':
                        field_chars.append('"')
                        i += 2
                        continue
                    else:
                        i += 1
                        # After closing quote: must be comma or end of line
                        if i < n and s[i] != ',':
                            raise ValueError("Invalid character after closing quote")
                        break
                else:
                    field_chars.append(ch)
                    i += 1
            fields.append("".join(field_chars))
            # If at comma, skip it and continue to next field
            if i < n and s[i] == ',':
                i += 1
                # If comma is terminal (i==n) will be handled at top loop
                # Continue parsing next field
                if i == n:
                    fields.append("")  # trailing empty field
                    return fields
                continue
            # else at end of line handled by loop condition
            if i >= n:
                return fields
        else:
            # unquoted field: read until comma or end
            start = i
            while i < n and s[i] != ',':
                if s[i] == '"':
                    raise ValueError("Quote in unquoted field")
                i += 1
