from collections import OrderedDict
from typing import Any, Callable

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float]):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        if ttl < 0:
            raise ValueError("ttl must be non-negative")
        self._capacity = capacity
        self._ttl = float(ttl)
        self._clock = clock
        # OrderedDict maps key -> (value, expire_time)
        # Order: least-recently-used at beginning, most-recently-used at end
        self._data = OrderedDict()

    def _purge_expired(self):
        now = self._clock()
        # Iterate from least-recently-used to most; stop when find unexpired
        keys_to_remove = []
        for k, (_, exp) in self._data.items():
            if now >= exp:
                keys_to_remove.append(k)
            else:
                break
        for k in keys_to_remove:
            self._data.pop(k, None)

    def set(self, key: Any, value: Any) -> None:
        self._purge_expired()
        now = self._clock()
        exp = now + self._ttl
        if key in self._data:
            # update value and expiry, mark as most-recently-used
            self._data.pop(key)
            self._data[key] = (value, exp)
        else:
            # ensure capacity
            while len(self._data) >= self._capacity:
                # evict least-recently-used (first item)
                self._data.popitem(last=False)
            self._data[key] = (value, exp)

    def get(self, key: Any):
        self._purge_expired()
        item = self._data.get(key)
        if item is None:
            return None
        value, exp = item
        now = self._clock()
        if now >= exp:
            # expired (should not happen because of purge, but defensive)
            self._data.pop(key, None)
            return None
        # mark as most-recently-used by moving to end
        self._data.pop(key)
        self._data[key] = (value, exp if self._ttl == 0 else now + self._ttl)
        # Note: per requirements, a get counts as a use and restarts ttl
        # We restart the ttl by updating expiry to now + ttl
        return value

    def __len__(self) -> int:
        self._purge_expired()
        return len(self._data)

