from typing import List, Set


def cron_matches(expr: str, minute: int, hour: int, dom: int, month: int, dow: int) -> bool:
    FIELD_RANGES = [
        (0, 59),  # minute
        (0, 23),  # hour
        (1, 31),  # day-of-month
        (1, 12),  # month
        (0, 7),   # day-of-week (0 and 7 both Sunday)
    ]

    def parse_field(field: str, idx: int) -> Set[int] or None:
        lo, hi = FIELD_RANGES[idx]
        field = field.strip()
        if field == "*":
            return None  # None means unrestricted

        def parse_number(s: str) -> int:
            if not s.isdigit():
                raise ValueError(f"Invalid number: {s}")
            n = int(s)
            # For dow allow 7 as Sunday but keep as 7; we'll map equivalently later
            if not (lo <= n <= hi):
                raise ValueError(f"Value {n} out of range for field {idx}")
            return n

        results = set()
        parts = field.split(',')
        if any(p == '' for p in parts):
            raise ValueError(f"Invalid list in field: {field}")
        for part in parts:
            if '/' in part:
                base, step_s = part.split('/', 1)
                if step_s == '' or not step_s.isdigit():
                    raise ValueError(f"Invalid step in field: {part}")
                step = int(step_s)
                if step < 1:
                    raise ValueError(f"Step must be >=1 in field: {part}")
            else:
                base = part
                step = 1

            if base == '*':
                start = lo
                end = hi
            elif '-' in base:
                a_b = base.split('-', 1)
                if len(a_b) != 2 or a_b[0] == '' or a_b[1] == '':
                    raise ValueError(f"Invalid range: {base}")
                a = parse_number(a_b[0])
                b = parse_number(a_b[1])
                if a > b:
                    raise ValueError(f"Descending range not allowed: {base}")
                start, end = a, b
            else:
                # single number (with optional step)
                n = parse_number(base)
                start = n
                end = n

            # generate values from start..end stepping by step
            val = start
            while val <= end:
                results.add(val)
                val += step

        return results

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expression must have exactly five fields")
    parsed = []
    for i, f in enumerate(fields):
        parsed.append(parse_field(f, i))

    # Normalize dow: map 7 to 0 for comparison since both mean Sunday
    def matches_field(parsed_field, value, idx):
        if parsed_field is None:
            return True
        if idx == 4:
            # map value 0..6 and allow 7==0
            vals = set(v % 7 for v in parsed_field)
            val = value % 7
            return val in vals
        else:
            return value in parsed_field

    minute_ok = matches_field(parsed[0], minute, 0)
    hour_ok = matches_field(parsed[1], hour, 1)
    dom_field_restricted = parsed[2] is not None
    dom_ok = matches_field(parsed[2], dom, 2)
    month_ok = matches_field(parsed[3], month, 3)
    dow_field_restricted = parsed[4] is not None
    dow_ok = matches_field(parsed[4], dow, 4)

    # Standard cron rule for dom and dow:
    if dom_field_restricted and dow_field_restricted:
        day_ok = dom_ok or dow_ok
    else:
        day_ok = dom_ok and dow_ok

    return minute_ok and hour_ok and month_ok and day_ok

