            a = int(a_s); b = int(b_s)
            if a > b:
                raise ValueError("descending range")
            start, end = a, b
        else:
            if base == '':
                raise ValueError("empty element")
            if not base.lstrip('-').isdigit():
                raise ValueError("invalid number")
            v = int(base)
            check_val(v)
            if step != 1:
                # single value with a step: either it matches if (value-start) % step ==0 where start is lo for '*' semantics,
                # but cron semantics normally allow "5/10" meaning starting at 5. We'll treat single value with step as range of that single value.
                if (v - lo) % step == 0:
                    results.add(v)
