            else:
                results.add(v)
            continue
        # generate values from start to end inclusive applying step
        if start < lo or end > hi:
            raise ValueError("range bounds out of field limits")
        val = start
        while val <= end:
            results.add(val)
            val += step
    # Special mapping for day-of-week: map 7 -> 0
    if idx == 4:
        if 7 in results:
            results.add(0)
            results.discard(7)
    return results

def cron_matches(expr: str, minute: int, hour: int, dom: int, month: int, dow: int) -> bool:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expression must have exactly five fields")
    vals = [minute, hour, dom, month, dow]
    for i, v in enumerate(vals):
        lo, hi = RANGES[i]
        if i == 4:
            # dow: allow 0-7 input; map 7->0 for matching
            if v == 7:
                v = 0
            elif v < lo or v > hi:
                raise ValueError("weekday out of range")
            vals[i] = v
        else:
            if v < lo or v > hi:
                raise ValueError("value out of range")
    parsed = []
    for i, field in enumerate(fields):
        parsed.append(_parse_field(field, i))
    # Determine matches
    m_match = vals[0] in parsed[0]
    h_match = vals[1] in parsed[1]
    dom_match = vals[2] in parsed[2]
    mon_match = vals[3] in parsed[3]
    dow_val = vals[4]
    # For day-of-week candidate, map 7->0 already handled
    dow_match = dow_val in parsed[4]
    # Month and time fields must match
    if not (m_match and h_match and mon_match):
        return False
    dom_restricted = fields[2] != '*'
    dow_restricted = fields[4] != '*'
    if dom_restricted and dow_restricted:
        return dom_match or dow_match
    else:
        return dom_match and dow_match

