def _two_digit(n: int) -> str:
    if n < 20:
        return ONES[n]
    tens = (n // 10) * 10
    ones = n % 10
    if ones == 0:
        return TENS[tens]
    return TENS[tens] + "-" + ONES[ones]

def _three_digit(n: int) -> str:
    # 0 <= n <= 999
    if n < 100:
        return _two_digit(n) if n != 0 else ""
    hundreds = n // 100
    rem = n % 100
    if rem == 0:
        return ONES[hundreds] + " hundred"
    # British English requires "and" between hundreds and the rest
    return ONES[hundreds] + " hundred and " + _two_digit(rem)

def number_to_words(n: int) -> str:
    if not isinstance(n, int):
        raise ValueError("n must be an int")
    if n < 0 or n >= 1_000_000:
        raise ValueError("n out of supported range (0 <= n < 1,000,000)")
    if n == 0:
        return "zero"
    thousands = n // 1000
    units = n % 1000
    parts: List[str] = []
    if thousands:
        # Form thousands group without inserting "and" inside it except its own hundreds rule
        if thousands < 100:
            # For values <100 in thousands group, use two-digit words (no trailing zero handling needed)
            thousands_part = _two_digit(thousands)
        else:
            thousands_part = _three_digit(thousands)
        thousands_part += " thousand"
        parts.append(thousands_part)
    if units:
        # Decide connector: if there is a thousands part and units < 100, British style uses "and" between thousands and remainder below 100
        if thousands and units < 100:
            connector = " and "
        elif thousands:
            connector = ", "
        else:
            connector = ""
        units_part = _three_digit(units)
        # _three_digit returns "" for 0; but units != 0 here
        parts.append(connector + units_part if connector else units_part)
