from collections import defaultdict, deque
import heapq
from typing import Dict, List

def topological_sort(deps: Dict[str, List[str]]) -> List[str]:
    # Collect all nodes: keys and those appearing in dependency lists
    nodes = set(deps.keys())
    for lst in deps.values():
        for v in lst:
            nodes.add(v)

    if not nodes:
        return []

    # Build incoming edge count (in-degree) and adjacency list for outgoing edges
    in_deg = {n: 0 for n in nodes}
    out_adj = defaultdict(list)  # node -> list of nodes that depend on it
    for node, depends in deps.items():
        for dep in depends:
            # edge dep -> node
            out_adj[dep].append(node)
            in_deg[node] += 1

    # Initialize min-heap with nodes of in-degree 0 (alphabetically smallest first)
    heap = [n for n, d in in_deg.items() if d == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in out_adj.get(n, ()):
            in_deg[m] -= 1
            if in_deg[m] == 0:
                heapq.heappush(heap, m)

    if len(order) != len(nodes):
        raise ValueError("cycle detected")
    return order

