from typing import Dict

def roman_to_int(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    if s == "":
        raise ValueError("Empty string is not a valid Roman numeral")
    # Only uppercase allowed
    if s != s.upper():
        raise ValueError("Lower-case letters are not allowed")
    # Valid symbols
    vals: Dict[str, int] = {'I':1, 'V':5, 'X':10, 'L':50, 'C':100, 'D':500, 'M':1000}
    for ch in s:
        if ch not in vals:
            raise ValueError(f"Invalid character {ch!r} in Roman numeral")
    # 1) No more than three of I, X, C, M in a row
    for ch in ('I','X','C','M'):
        if ch * 4 in s:
            raise ValueError(f"Too many repeats of {ch}")
    # 2) V, L, D never repeated
    for ch in ('V','L','D'):
        if ch*2 in s:
            raise ValueError(f"Illegal repeat of {ch}")
    # 3) Only allowed subtractive pairs
    allowed_subtractives = {'IV','IX','XL','XC','CD','CM'}
    i = 0
    n = len(s)
    combined_values = []
    # Parse and validate subtractive usage and repeats adjacent to subtractives
    while i < n:
        ch = s[i]
        val = vals[ch]
        if i+1 < n:
            nxt = s[i+1]
            nxtval = vals[nxt]
            if val < nxtval:
                pair = ch + nxt
                if pair not in allowed_subtractives:
                    raise ValueError(f"Invalid subtractive pair {pair}")
                # small numeral must not be repeated before subtractive pair (e.g., IIX)
                if i-1 >= 0 and s[i-1] == ch:
                    raise ValueError(f"Invalid repetition before subtractive pair {pair}")
                combined_values.append(nxtval - val)
                i += 2
                continue
        combined_values.append(val)
        i += 1
    # Combined values must be non-increasing for canonical form
    for j in range(1, len(combined_values)):
        if combined_values[j] > combined_values[j-1]:
            raise ValueError("Numerals not in canonical order")
    total = sum(combined_values)
    if total < 1 or total > 3999:
        raise ValueError("Result out of range (1..3999) or invalid numeral")
    # Additional check: a subtractive pair's small symbol must not appear immediately after the pair (e.g., IXI)
    i = 0
    while i < n:
        if i+1 < n and s[i:i+2] in allowed_subtractives:
            small = s[i]
            if i+2 < n and s[i+2] == small:
                raise ValueError(f"Invalid repetition around subtractive pair {s[i:i+2]}")
            i += 2
        else:
            i += 1
    return total

