    (?P<patch>0|[1-9]\d*)
    (?:-(?P<prerelease>[^+\s]+))?                  # prerelease (no spaces, stops at +)
    (?:\+(?P<build>.+))?$                          # build is rest of string
    """,
    re.VERBOSE,
)


