    if s == "":
        raise ValueError("empty identifier string")
    parts = s.split(".")
    result: list[Identifier] = []
    for p in parts:
        if p == "":
            raise ValueError("empty identifier")
        # numeric identifier must not have leading zeros unless exactly "0"
        if re.fullmatch(r"\d+", p):
            if len(p) > 1 and p[0] == "0":
                raise ValueError(f"numeric identifier with leading zero: {p}")
            val = int(p)
            result.append(val)
        else:
            # must consist of ASCII alphanumerics and hyphens per semver spec
            if not re.fullmatch(r"[0-9A-Za-z-]+", p):
                raise ValueError(f"invalid prerelease identifier: {p}")
            result.append(p)
