    minor_s = m.group("minor")
    patch_s = m.group("patch")
    major = int(major_s)
    minor = int(minor_s)
    patch = int(patch_s)
    if major < 0 or minor < 0 or patch < 0:
        raise ValueError("negative numeric version part")
    prerelease_raw = m.group("prerelease")
    build = m.group("build") or ""
    if prerelease_raw is None:
        prerelease = tuple()
